// This source file was generated by a Codex agent.
//
// The protocol model follows the PMC-Eight Programmer's Reference and what an iEXOS-100 with
// firmware 20A01.1 answered on its serial port (recorded 2026-09-24):
// - Every SET command is answered with the matching GET reply: ESSd -> ESGd, ESSr -> ESGr,
//   ESTr -> ESGx, ESSp -> ESGp, ESPt -> ESGt.
// - ESSr sets an axis rate in counts per second, ESTr the right ascension tracking rate in 1/25
//   counts per second. ESSd selects the direction: 1 makes the counts grow, 0 makes them shrink,
//   and the tracking rate shares the right ascension direction. ESGr reports counts per second.
// - ESPt points an axis at a target at 40000 (right ascension) and 39800 (declination) counts per
//   second. While a point runs, a rate or direction command is answered only after about 1.5 s and
//   then ends the point on its axis; ESPt300000 ends the point on both axes at once and answers
//   ESGt3.
// - Closing the serial port drops DTR and reboots the controller: both axes stop, the position
//   counters and the tracking rate are cleared, and nothing is answered until the boot is over
//   (13.9 s on the real controller, --boot-seconds here, 2 s by default).
// --speed-scale shortens the long slews a test does not want to wait for; the rate the controller
// reports while pointing stays the real one.
//
// Events ("<ready-file>.events"): "<monotonic seconds>\t<command>" for every command received, and
// "REBOOT" when the controller reboots.

#define _DEFAULT_SOURCE
#define _XOPEN_SOURCE 600

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <math.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <netinet/in.h>
#include <unistd.h>

#include "../../../indigo_test/simulator_common/serial_simulator_common.h"
#include "../../../indigo_test/simulator_common/serial_motion.h"

typedef struct {
	bool headless;
	bool trace;
	bool network;
	bool iexos100;
	double boot_seconds;
	double speed_scale;
	const char *ready_file;
} simulator_options;

typedef struct {
	serial_motion point[2];
	bool pointing[2];
	int32_t target[2];
	double position[2];
	int rate[2];
	int direction[2];
	int tracking_rate;
	bool rate_is_tracking;
	double updated;
	double booted;
} simulator_state;

static simulator_options options = {
	.headless = false,
	.trace = false,
	.network = false,
	.iexos100 = false,
	.boot_seconds = 2.0,
	.speed_scale = 1.0,
	.ready_file = NULL
};
static simulator_state state = { 0 };
static const double point_speed[2] = { 40000, 39800 };
static FILE *events = NULL;
static const char *simulator_name = "mount_pmc8";
static volatile sig_atomic_t running = 1;
static int serial_fd = -1;
static int tcp_fd = -1;
static int tcp_client_fd = -1;
static int udp_fd = -1;

static void usage(const char *name) {
	printf("PMC-Eight mount serial simulator\n");
	printf("Usage: %s [OPTIONS]\n", name);
	printf("  --headless              Disable terminal-oriented output\n");
	printf("  --network               Enable loopback TCP and UDP listeners\n");
	printf("  --ready-file <path>     Write simulator connection details after setup\n");
	printf("  --trace                 Log protocol requests and replies\n");
	printf("  --model <exos2|iexos100> Identity strings to report (default exos2)\n");
	printf("  --boot-seconds <s>      Silence after a reboot (default 2)\n");
	printf("  --speed-scale <x>       Point faster than the real controller, for long test slews\n");
	printf("  -h, --help              Show this help and exit\n");
}

static bool parse_args(int argc, char *argv[]) {
	for (int i = 1; i < argc; i++) {
		if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
			usage(argv[0]);
			exit(0);
		} else if (!strcmp(argv[i], "--headless")) {
			options.headless = true;
			options.trace = false;
		} else if (!strcmp(argv[i], "--network")) {
			options.network = true;
		} else if (!strcmp(argv[i], "--trace")) {
			options.trace = true;
		} else if (!strcmp(argv[i], "--model")) {
			if (++i == argc) {
				fprintf(stderr, "--model requires a value\n");
				return false;
			}
			options.iexos100 = !strcmp(argv[i], "iexos100");
		} else if (!strcmp(argv[i], "--boot-seconds")) {
			if (++i == argc) {
				fprintf(stderr, "--boot-seconds requires a value\n");
				return false;
			}
			options.boot_seconds = atof(argv[i]);
		} else if (!strcmp(argv[i], "--speed-scale")) {
			if (++i == argc) {
				fprintf(stderr, "--speed-scale requires a value\n");
				return false;
			}
			options.speed_scale = atof(argv[i]);
		} else if (!strcmp(argv[i], "--ready-file")) {
			if (++i == argc) {
				fprintf(stderr, "--ready-file requires a path\n");
				return false;
			}
			options.ready_file = argv[i];
		} else {
			fprintf(stderr, "Unknown option '%s'\n", argv[i]);
			return false;
		}
	}
	return true;
}

static void signal_handler(int sig) {
	(void)sig;
	running = 0;
	if (serial_fd >= 0) {
		close(serial_fd);
		serial_fd = -1;
	}
	if (tcp_client_fd >= 0) {
		close(tcp_client_fd);
		tcp_client_fd = -1;
	}
	if (tcp_fd >= 0) {
		close(tcp_fd);
		tcp_fd = -1;
	}
	if (udp_fd >= 0) {
		close(udp_fd);
		udp_fd = -1;
	}
}

static bool set_nonblocking(int fd) {
	int flags = fcntl(fd, F_GETFL, 0);
	if (flags < 0) {
		return false;
	}
	return fcntl(fd, F_SETFL, flags | O_NONBLOCK) == 0;
}

static bool open_loopback_socket(int type, int port, int *fd, int *bound_port) {
	*fd = socket(AF_INET, type, 0);
	if (*fd < 0) {
		perror("socket");
		return false;
	}
	int reuse = 1;
	setsockopt(*fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));

	struct sockaddr_in address;
	memset(&address, 0, sizeof(address));
	address.sin_family = AF_INET;
	address.sin_addr.s_addr = inet_addr("127.0.0.1");
	address.sin_port = htons(port);
	if (bind(*fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
		perror("bind");
		close(*fd);
		*fd = -1;
		return false;
	}
	socklen_t length = sizeof(address);
	if (getsockname(*fd, (struct sockaddr *)&address, &length) < 0) {
		perror("getsockname");
		close(*fd);
		*fd = -1;
		return false;
	}
	*bound_port = ntohs(address.sin_port);
	if (!set_nonblocking(*fd)) {
		perror("fcntl");
		close(*fd);
		*fd = -1;
		return false;
	}
	return true;
}

static bool open_network_sockets(int *port) {
	if (!open_loopback_socket(SOCK_STREAM, 0, &tcp_fd, port)) {
		return false;
	}
	if (listen(tcp_fd, 4) < 0) {
		perror("listen");
		close(tcp_fd);
		tcp_fd = -1;
		return false;
	}
	int udp_port = 0;
	if (!open_loopback_socket(SOCK_DGRAM, *port, &udp_fd, &udp_port)) {
		close(tcp_fd);
		tcp_fd = -1;
		return false;
	}
	if (udp_port != *port) {
		close(udp_fd);
		close(tcp_fd);
		udp_fd = -1;
		tcp_fd = -1;
		return false;
	}
	return true;
}

static bool write_ready_file(const char *ready_file, const char *port, int network_port) {
	char tmp_file[PATH_MAX];
	snprintf(tmp_file, sizeof(tmp_file), "%s.tmp.%ld", ready_file, (long)getpid());

	FILE *file = fopen(tmp_file, "w");
	if (file == NULL) {
		perror("fopen ready file");
		return false;
	}

	fprintf(file, "INDIGO_SIMULATOR=%s\n", simulator_name);
	fprintf(file, "INDIGO_SIMULATOR_PORT=%s\n", port);
	fprintf(file, "INDIGO_SIMULATOR_TCP_URL=tcp://127.0.0.1:%d\n", network_port);
	fprintf(file, "INDIGO_SIMULATOR_UDP_URL=udp://127.0.0.1:%d\n", network_port);
	fprintf(file, "INDIGO_SIMULATOR_PID=%ld\n", (long)getpid());
	if (fclose(file) != 0) {
		perror("fclose ready file");
		unlink(tmp_file);
		return false;
	}

	if (rename(tmp_file, ready_file) != 0) {
		perror("rename ready file");
		unlink(tmp_file);
		return false;
	}
	return true;
}

static void write_response(int fd, const char *response) {
	if (options.trace) {
		fprintf(stderr, "<- %s\n", response);
	}
	serial_simulator_write_all(fd, response, strlen(response));
}

static void write_udp_response(const struct sockaddr_in *client_address, socklen_t client_address_length, const char *response) {
	if (options.trace) {
		fprintf(stderr, "<- %s\n", response);
	}
	sendto(udp_fd, response, strlen(response), 0, (const struct sockaddr *)client_address, client_address_length);
}

static void log_event(const char *text) {
	if (events != NULL) {
		fprintf(events, "%.9f\t%s\n", serial_motion_time(), text);
		fflush(events);
	}
}

static int axis_from_command(const char *command, size_t index) {
	if (strlen(command) <= index || (command[index] != '0' && command[index] != '1')) {
		return -1;
	}
	return command[index] - '0';
}

// The counts an axis turns per second while it is not pointing, signed by its direction.
static double axis_speed(int axis) {
	double speed = axis == 0 && state.rate_is_tracking ? state.tracking_rate / 25.0 : state.rate[axis];
	return state.direction[axis] ? speed : -speed;
}

static void update_motion(void) {
	double now = serial_motion_time();
	for (int axis = 0; axis < 2; axis++) {
		if (state.pointing[axis]) {
			state.position[axis] = serial_motion_update(&state.point[axis]);
			if (state.point[axis].duration == 0) {
				state.pointing[axis] = false;
			}
		} else {
			state.position[axis] += axis_speed(axis) * (now - state.updated);
		}
	}
	state.updated = now;
}

static void stop_point(int axis) {
	if (state.pointing[axis]) {
		serial_motion_stop(&state.point[axis]);
		state.position[axis] = state.point[axis].position;
		state.pointing[axis] = false;
	}
}

static void reboot(void) {
	memset(&state, 0, sizeof(state));
	state.updated = serial_motion_time();
	state.booted = state.updated + options.boot_seconds;
	log_event("REBOOT");
}

static int32_t position_of(int axis) {
	return (int32_t)lround(state.position[axis]);
}

// A rate or direction command reaches a pointing controller late, and only then ends the point.
static void settle_point(int axis) {
	if (state.pointing[0] || state.pointing[1]) {
		usleep(1500000);
		update_motion();
		stop_point(axis);
	}
}

static const char *build_response(const char *command, char *response, size_t response_size) {
	if (options.trace) {
		fprintf(stderr, "-> %s\n", command);
	}
	log_event(command);
	update_motion();
	if (serial_motion_time() < state.booted) {
		return NULL;
	}
	if (!strcmp(command, "ESGv!")) {
		return options.iexos100 ? "ESGvES20A01.1 Release 2021.08.08: ES1A01CB20A01, ESP8266, DST4!" : "ESGvES20200301 EXOS2 20!";
	} else if (!strcmp(command, "ESGi!")) {
		return options.iexos100 ? "ESGi1152000001040040000900060000001!" : "ESGi0000000000000000080000!";
	} else if (!strcmp(command, "ESGx!")) {
		snprintf(response, response_size, "ESGx%04X!", state.tracking_rate & 0xFFFF);
		return response;
	} else if (!strncmp(command, "ESSd", 4)) {
		int axis = axis_from_command(command, 4);
		if (axis < 0) {
			return command;
		}
		settle_point(axis);
		state.direction[axis] = command[5] == '0' ? 0 : 1;
		snprintf(response, response_size, "ESGd%d%d!", axis, state.direction[axis]);
		return response;
	} else if (!strncmp(command, "ESTr", 4)) {
		settle_point(0);
		state.tracking_rate = (int)strtol(command + 4, NULL, 16);
		state.rate_is_tracking = true;
		snprintf(response, response_size, "ESGx%04X!", state.tracking_rate & 0xFFFF);
		return response;
	} else if (!strncmp(command, "ESSr", 4)) {
		int axis = axis_from_command(command, 4);
		if (axis < 0) {
			return command;
		}
		settle_point(axis);
		state.rate[axis] = (int)strtol(command + 5, NULL, 16);
		if (axis == 0) {
			state.rate_is_tracking = false;
		}
		snprintf(response, response_size, "ESGr%d%04X!", axis, state.rate[axis] & 0xFFFF);
		return response;
	} else if (!strcmp(command, "ESPt300000!")) {
		stop_point(0);
		stop_point(1);
		return "ESGt3!";
	} else if (!strncmp(command, "ESPt", 4)) {
		int axis = axis_from_command(command, 4);
		if (axis < 0) {
			return command;
		}
		int32_t target = (int32_t)strtol(command + 5, NULL, 16);
		if (target & 0x800000) {
			target |= (int32_t)0xFF000000;
		}
		state.target[axis] = target;
		if (axis == 0) {
			state.rate_is_tracking = false;
		}
		state.rate[axis] = 0;
		serial_motion_sync(&state.point[axis], state.position[axis]);
		serial_motion_start(&state.point[axis], target, point_speed[axis] * options.speed_scale);
		state.pointing[axis] = true;
		snprintf(response, response_size, "ESGt%d%06X!", axis, target & 0xFFFFFF);
		return response;
	} else if (!strncmp(command, "ESSp", 4)) {
		int axis = axis_from_command(command, 4);
		if (axis < 0) {
			return command;
		}
		int32_t position = (int32_t)strtol(command + 5, NULL, 16);
		if (position & 0x800000) {
			position |= (int32_t)0xFF000000;
		}
		stop_point(axis);
		state.position[axis] = position;
		snprintf(response, response_size, "ESGp%d%06X!", axis, position & 0xFFFFFF);
		return response;
	} else if (!strncmp(command, "ESGp", 4)) {
		int axis = axis_from_command(command, 4);
		snprintf(response, response_size, "ESGp%d%06X!", axis < 0 ? 0 : axis, axis < 0 ? 0 : position_of(axis) & 0xFFFFFF);
		return response;
	} else if (!strncmp(command, "ESGt", 4)) {
		int axis = axis_from_command(command, 4);
		snprintf(response, response_size, "ESGt%d%06X!", axis < 0 ? 0 : axis, axis < 0 ? 0 : state.target[axis] & 0xFFFFFF);
		return response;
	} else if (!strncmp(command, "ESGr", 4)) {
		int axis = axis_from_command(command, 4);
		int rate = 0;
		if (axis >= 0) {
			rate = state.pointing[axis] ? (int)point_speed[axis] : (int)lround(fabs(axis_speed(axis)));
		}
		snprintf(response, response_size, "ESGr%d%04X!", axis < 0 ? 0 : axis, rate & 0xFFFF);
		return response;
	} else if (!strncmp(command, "ESGd", 4)) {
		int axis = axis_from_command(command, 4);
		snprintf(response, response_size, "ESGd%d%d!", axis < 0 ? 0 : axis, axis < 0 ? 0 : state.direction[axis]);
		return response;
	} else if (!strcmp(command, "ESY!")) {
		return "ESY0!";
	} else if (!strcmp(command, "ESX!")) {
		return "ESX0!";
	} else {
		return command;
	}
}

static void handle_command(int fd, const char *command) {
	char response[96] = { 0 };
	const char *reply = build_response(command, response, sizeof(response));
	if (reply != NULL) {
		write_response(fd, reply);
	}
}

static void handle_udp_command(const struct sockaddr_in *client_address, socklen_t client_address_length, const char *command) {
	char response[96] = { 0 };
	const char *reply = build_response(command, response, sizeof(response));
	if (reply != NULL) {
		write_udp_response(client_address, client_address_length, reply);
	}
}

// Whether a driver has the pseudo terminal open, so its hang-up can be told from a terminal nobody
// opened yet: both read as EIO or end of file.
static bool serial_client = false;

static void process_stream_input(int fd, char *command, size_t *length) {
	char buffer[64];
	ssize_t count = read(fd, buffer, sizeof(buffer));
	if (fd == serial_fd) {
		if (count > 0) {
			serial_client = true;
		} else if (count == 0 || (count < 0 && errno == EIO)) {
			if (serial_client) {
				serial_client = false;
				*length = 0;
				reboot();
			}
			usleep(10000);
			return;
		}
	}
	if (count > 0) {
		for (ssize_t i = 0; i < count; i++) {
			if (*length + 1 < 64) {
				command[(*length)++] = buffer[i];
			}
			if (buffer[i] == '!') {
				command[*length] = 0;
				handle_command(fd, command);
				*length = 0;
			}
		}
	} else if (count < 0 && !(errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO)) {
		if (fd == tcp_client_fd) {
			close(tcp_client_fd);
			tcp_client_fd = -1;
			*length = 0;
		} else {
			running = 0;
		}
	} else if (count == 0 && fd == tcp_client_fd) {
		close(tcp_client_fd);
		tcp_client_fd = -1;
		*length = 0;
	}
}

int main(int argc, char *argv[]) {
	if (!parse_args(argc, argv)) {
		return 2;
	}

	state.updated = serial_motion_time();
	if (options.ready_file != NULL) {
		char path[PATH_MAX];
		snprintf(path, sizeof(path), "%s.events", options.ready_file);
		events = fopen(path, "w");
	}
	char port[PATH_MAX];
	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	int network_port = 0;
	if (options.network && !open_network_sockets(&network_port)) {
		close(serial_fd);
		return 1;
	}
	if (options.ready_file != NULL) {
		bool ready = options.network ? write_ready_file(options.ready_file, port, network_port) : serial_simulator_write_ready_file(options.ready_file, simulator_name, port);
		if (!ready) {
			close(serial_fd);
			if (tcp_fd >= 0) {
				close(tcp_fd);
			}
			if (udp_fd >= 0) {
				close(udp_fd);
			}
			return 1;
		}
	}
	if (!options.headless) {
		printf("PMC-Eight mount simulator ready on %s\n", port);
		if (options.network) {
			printf("PMC-Eight mount simulator TCP ready on tcp://127.0.0.1:%d\n", network_port);
			printf("PMC-Eight mount simulator UDP ready on udp://127.0.0.1:%d\n", network_port);
		}
	}

	signal(SIGINT, signal_handler);
	signal(SIGTERM, signal_handler);

	char serial_command[64] = { 0 };
	size_t serial_length = 0;
	char tcp_command[64] = { 0 };
	size_t tcp_length = 0;
	while (running) {
		fd_set readfds;
		FD_ZERO(&readfds);
		FD_SET(serial_fd, &readfds);
		int max_fd = serial_fd;
		if (tcp_fd >= 0) {
			FD_SET(tcp_fd, &readfds);
		}
		if (udp_fd >= 0) {
			FD_SET(udp_fd, &readfds);
		}
		if (tcp_fd >= 0 && tcp_fd > max_fd) {
			max_fd = tcp_fd;
		}
		if (udp_fd >= 0 && udp_fd > max_fd) {
			max_fd = udp_fd;
		}
		if (tcp_client_fd >= 0) {
			FD_SET(tcp_client_fd, &readfds);
			if (tcp_client_fd > max_fd) {
				max_fd = tcp_client_fd;
			}
		}
		struct timeval timeout = { 0, 100000 };
		int selected = select(max_fd + 1, &readfds, NULL, NULL, &timeout);
		if (selected < 0) {
			if (errno == EINTR) {
				continue;
			}
			break;
		}
		if (selected == 0) {
			continue;
		}
		if (tcp_fd >= 0 && FD_ISSET(tcp_fd, &readfds)) {
			struct sockaddr_in client_address;
			socklen_t client_address_length = sizeof(client_address);
			int client_fd = accept(tcp_fd, (struct sockaddr *)&client_address, &client_address_length);
			if (client_fd >= 0) {
				set_nonblocking(client_fd);
				if (tcp_client_fd >= 0) {
					close(tcp_client_fd);
				}
				tcp_client_fd = client_fd;
				tcp_length = 0;
			}
		}
		if (udp_fd >= 0 && FD_ISSET(udp_fd, &readfds)) {
			char buffer[64];
			struct sockaddr_in client_address;
			socklen_t client_address_length = sizeof(client_address);
			ssize_t count = recvfrom(udp_fd, buffer, sizeof(buffer) - 1, 0, (struct sockaddr *)&client_address, &client_address_length);
			if (count > 0) {
				buffer[count] = 0;
				handle_udp_command(&client_address, client_address_length, buffer);
			}
		}
		if (FD_ISSET(serial_fd, &readfds)) {
			process_stream_input(serial_fd, serial_command, &serial_length);
		}
		if (tcp_client_fd >= 0 && FD_ISSET(tcp_client_fd, &readfds)) {
			process_stream_input(tcp_client_fd, tcp_command, &tcp_length);
		}
	}
	if (tcp_client_fd >= 0) {
		close(tcp_client_fd);
	}
	if (tcp_fd >= 0) {
		close(tcp_fd);
	}
	if (udp_fd >= 0) {
		close(udp_fd);
	}
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	if (events != NULL) {
		fclose(events);
	}
	return 0;
}
